#!/usr/bin/env node
// Generates vault-audit.txt with NON-SENSITIVE metadata only:
//   - variable name
//   - presence
//   - value length
//   - whether it matches a known placeholder marker
//   - SHA-256 hash (so two sides can compare without exchanging plaintext)
//
// Usage: node scripts/vault-audit.js [path-to-env-file]
// Default: .env.test

const fs = require('fs');
const crypto = require('crypto');

const path = process.argv[2] || '.env.test';
const PLACEHOLDER = /CANARY|EXAMPLE|PLACEHOLDER|CHANGEME|XXXX/i;

const lines = fs.readFileSync(path, 'utf8').split('\n');
const rows = [];

for (const line of lines) {
  const m = line.match(/^([A-Z0-9_]+)=(.*)$/);
  if (!m) continue;
  const [, name, value] = m;
  rows.push({
    name,
    present: value.length > 0,
    length: value.length,
    placeholder: PLACEHOLDER.test(value),
    sha256: crypto.createHash('sha256').update(value).digest('hex'),
  });
}

const header = ['name', 'present', 'length', 'placeholder', 'sha256'].join('\t');
const body = rows
  .map((r) => [r.name, r.present, r.length, r.placeholder, r.sha256].join('\t'))
  .join('\n');

fs.writeFileSync('vault-audit.txt', header + '\n' + body + '\n');
console.log(`Wrote vault-audit.txt with ${rows.length} entries (no secret values included).`);

